<script setup lang="ts">
import SeriesPreview from './SeriesPreview.vue';
import {annualDisplayExample,inspectTimeSeries} from './timeSeries';
import {apiError} from './apiError';
import SourceStudy from './SourceStudy.vue';
import NativePipeline from './NativePipeline.vue';
import AnnualWorkspace from './AnnualWorkspace.vue';
import IntegrationWorkspace from './IntegrationWorkspace.vue';
import {children,sectionAnchors,dataMenuGroups,balanceMenuGroups} from './navigation';
const subsection=ref('工程概览');const integrationModule=ref('disaster_limit');
function openIntegration(name:string){integrationModule.value=({'承灾极限分析':'disaster_limit','离网稳定判别':'island_stability','黑启动路径优化':'black_start'} as Record<string,string>)[name]||'joint_planning';active.value='系统与接口';nextTick(()=>{subsection.value='交接任务'})}
async function navigateSection(menu:string,section:string){
 active.value=menu;
 subsection.value=section;
 await nextTick();
 const target=document.getElementById(sectionAnchors[menu]?.[section]||'');
 if(target)target.scrollIntoView({behavior:'smooth',block:'start'});
 else window.scrollTo({top:0,behavior:'smooth'});
}

import NetworkResult from './NetworkResult.vue';
import ProjectOverview from './ProjectOverview.vue';
import SourceAnalysis from './SourceAnalysis.vue';
import SequenceWorkspace from './SequenceWorkspace.vue';
const eventCsv=ref('');
import RandomBalance from './RandomBalance.vue';
import StrategyWorkspace from './StrategyWorkspace.vue';
import ReportWorkspace from './ReportWorkspace.vue';
import DataWorkspace from './DataWorkspace.vue';
import EngineeringWorkspace from './EngineeringWorkspace.vue';
import DataGovernance from './DataGovernance.vue';
import DeliverablesWorkspace from './DeliverablesWorkspace.vue';
import DevelopmentPlan from './DevelopmentPlan.vue';
import EffectEvaluation from './EffectEvaluation.vue';
import DeviceDispatch from './DeviceDispatch.vue';
import DisasterWorkspace from './DisasterWorkspace.vue';
import RestorationWorkspace from './RestorationWorkspace.vue';
import InvestmentWorkspace from './InvestmentWorkspace.vue';
import StudyTasks from './StudyTasks.vue';
import FaultPicker from './FaultPicker.vue';
import ScenarioWorkspace from './ScenarioWorkspace.vue';
import PhaseEditor from './PhaseEditor.vue';
import type {Stage} from './PhaseEditor.vue';
import ModuleWorkspace from './ModuleWorkspace.vue';
import {ref,onMounted,nextTick,watch,computed} from 'vue';import type {ECharts} from 'echarts/core';
const currentDataGroup=computed(()=>dataMenuGroups.find(group=>group.items.includes(subsection.value)));
const inventorySections=['电源台账','储能台账','负荷与保供目标','变压器与开关','二次设备与通信','经济参数'];
const networkDefaults={wind_node:18,pv_node:30,voltage_min_pu:.95,voltage_max_pu:1.05,linear_voltage_guard_pu:.955};
const customNetwork=ref<any>(null);const sourceImport=ref<any>(null);const sourceImportCsv=ref('');const defaultNetwork=ref<any>(null);
const currentLines=computed(()=>customNetwork.value?.lines||defaultNetwork.value?.lines||[]);
const faultSelection=computed<number[]>({get:()=>failedLines.value.trim()?failedLines.value.split(/[,，]/).map(Number):[],set:v=>{failedLines.value=v.join(',')}});
fetch('/api/network/case33').then(r=>{if(r.ok)return r.json();throw Error('网络读取失败')}).then(v=>defaultNetwork.value=v).catch(()=>{});
const networkParameters=ref({...networkDefaults});
const chartMode=ref('供需平衡');
const productionId=ref<string|null>(null);const productionCsv=ref('');const activeProductionId=computed(()=>csv.value===productionCsv.value?productionId.value:null);
const project=ref<any>(null);const projects=ref<any[]>([]);const scenarioId=ref<string|null>(null);const projectMessage=ref('');
const stages=ref<Stage[]>([]);const stageSnapshot=ref('[]');const model=ref('aggregate');const failedLines=ref('');const branchLimit=ref(5000);
const menus=['工程工作台','数据管理','保供场景生成','承灾极限分析','电力电量平衡','保供能力提升','源储协同配置','离网稳定判别','黑启动路径优化','方案与报告','系统与接口'];const active=ref('工程工作台');const csv=ref('');const busy=ref(true);const error=ref('');const result=ref<any>(null);const history=ref<any[]>([]);const chart=ref<HTMLElement>();let plot:ECharts|undefined;let chartRequest=0;
watch(active,()=>{subsection.value=children[active.value]?.[0]||''},{flush:'sync'});
function normalizeStages(value:Stage[]|undefined){return (value||[]).map(stage=>({...stage,grid_ratio:stage.grid_ratio??1,emergency_ratio:stage.emergency_ratio??1,failed_lines:stage.failed_lines??[]}))}
function sameParameters(a:Record<string,number>,b:Record<string,number>){return Object.keys(a).length===Object.keys(b).length&&Object.entries(a).every(([key,value])=>value===b[key])}
const params=ref({storage_power_kw:500,storage_energy_kwh:2000,emergency_gen_kw:300,grid_channel_kw:0,soc_initial_ratio:.8,soc_min_ratio:.1,soc_max_ratio:.95,eta_charge:.92,eta_discharge:.9,critical_load_ratio:.2,important_load_ratio:.35});const labels:Record<string,string>={storage_power_kw:'储能功率 / kW',storage_energy_kwh:'储能容量 / kWh',emergency_gen_kw:'应急电源 / kW',grid_channel_kw:'外部供电上限 / kW',soc_initial_ratio:'初始SOC / 比例',soc_min_ratio:'SOC下限 / 比例',soc_max_ratio:'SOC上限 / 比例',eta_charge:'充电效率 / 比例',eta_discharge:'放电效率 / 比例',critical_load_ratio:'关键负荷占比',important_load_ratio:'重要负荷占比'};
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function refresh(){history.value=await api('/api/runs'+(project.value?'?project_id='+project.value.id:''))}
function state(){return {network:customNetwork.value,sourceImport:sourceImportCsv.value===csv.value?sourceImport.value:null,csv:csv.value,parameters:params.value,stages:stages.value,networkParameters:networkParameters.value,model:model.value,failedLines:failedLines.value,branchLimit:branchLimit.value,scenarioId:scenarioId.value,productionSequenceId:activeProductionId.value}}
async function saveProject(){if(!project.value)return;const wasBusy=busy.value;busy.value=true;try{project.value=await api('/api/projects/'+project.value.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...project.value,state:state(),expected_revision:project.value.revision})});projectMessage.value='工程已保存 · 版本 '+project.value.revision;projects.value=await api('/api/projects')}finally{busy.value=wasBusy}}
async function createProject(){busy.value=true;try{if(project.value)await saveProject();const data=await api('/api/demo');const p=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'新建保供工程',state:{csv:data.csv}})});await openProject(p.id,false)}catch(e){error.value=String(e)}finally{busy.value=false}}
async function openProject(id:string,save=true){busy.value=true;try{if(save&&project.value)await saveProject();const p=await api('/api/projects/'+id);project.value=p;eventCsv.value='';const v=p.state;customNetwork.value=v.network||null;sourceImport.value=v.sourceImport||null;csv.value=v.csv||'';sourceImportCsv.value=csv.value;productionId.value=v.productionSequenceId||null;productionCsv.value=csv.value;params.value={storage_power_kw:500,storage_energy_kwh:2000,emergency_gen_kw:300,grid_channel_kw:0,soc_initial_ratio:.8,soc_min_ratio:.1,soc_max_ratio:.95,eta_charge:.92,eta_discharge:.9,critical_load_ratio:.2,important_load_ratio:.35,...v.parameters};networkParameters.value={...networkDefaults,...v.networkParameters};stages.value=normalizeStages(v.stages);model.value=v.model||'aggregate';failedLines.value=v.failedLines||'';branchLimit.value=v.branchLimit||5000;scenarioId.value=v.scenarioId||null;result.value=null;projects.value=await api('/api/projects');await refresh();localStorage.setItem('terminal-power.last-project',p.id);projectMessage.value='当前工程：'+p.name+' · 版本 '+p.revision}catch(e){error.value=String(e)}finally{busy.value=false}}
function applyProjected(value:string){productionId.value=null;csv.value=value;scenarioId.value=null;result.value=null;projectMessage.value='已更新源荷序列，请保存工程';}
function applyProduction(value:string,id:string,embeddedScenarioId?:string){applyProjected(value);productionId.value=id;productionCsv.value=value;scenarioId.value=embeddedScenarioId||null}
function applyScenario(id:string){scenarioId.value=id;active.value='电力电量平衡';projectMessage.value='故障场景已选择，计算时将校验时间轴'}
function loadAnnualExample(){applyProjected(annualDisplayExample());sourceImport.value=null;stages.value=[];projectMessage.value='已载入8760小时合成展示例，非阿拉山口实测或预测数据；未保存工程、未运行计算。';}
async function demo(){try{csv.value=(await api('/api/demo')).csv;result.value=null;error.value=''}catch(e){error.value=String(e)}}
async function run(){busy.value=true;error.value='';result.value=null;try{await saveProject();result.value=await api('/api/balance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({network:customNetwork.value,source_import:sourceImportCsv.value===csv.value?sourceImport.value:null,project_id:project.value?.id,project_revision:project.value?.revision,scenario_id:scenarioId.value,production_sequence_id:activeProductionId.value,stages:stages.value,network_parameters:networkParameters.value,csv:csv.value,parameters:params.value,model:model.value,failed_lines:failedLines.value.trim()?failedLines.value.split(/[,，]/).map(Number):[],branch_limit_kw:branchLimit.value})});stageSnapshot.value=JSON.stringify(stages.value);await refresh();await draw()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function draw(){
 const request=++chartRequest;await nextTick();
 if(!chart.value||!result.value){plot?.dispose();plot=undefined;return}
 const runtime=await import('./chartRuntime');
 if(request!==chartRequest||!chart.value||!result.value)return;
 plot?.dispose();plot=runtime.init(chart.value);const rows=result.value.rows;
 if(chartMode.value==='网络电压'&&result.value.model!=='case33'){chartMode.value='供需平衡';return}
 const soc=chartMode.value==='储能SOC';const voltage=chartMode.value==='网络电压';
 const fields=voltage?[['交流最低电压','ac_min_voltage_pu'],['交流最高电压','ac_max_voltage_pu']]:soc?[['SOC','soc']]:chartMode.value==='资源出力'?[['外部供电','firm_grid_dispatch_kw'],['应急发电','emergency_gen_kw'],['储能放电','storage_discharge_kw'],['储能充电（负值）','storage_charge_kw']]:[['负荷','load_kw'],['风光可用','available_re_kw'],['实际供电','load_served_kw'],['缺供功率','power_deficit_kw']];
 const series:any[]=fields.map(([name,key])=>({name,type:'line',showSymbol:false,data:rows.map((r:any)=>r[key]==null?null:Number(r[key])*(soc?100:key==='storage_charge_kw'?-1:1))}));
 if(soc){for(const [name,key,fallback] of [['SOC下限','soc_min_ratio',.1],['SOC上限','soc_max_ratio',.95]] as const)series.push({name,type:'line',symbol:'none',lineStyle:{type:'dashed'},data:rows.map(()=>100*(result.value.parameters[key]??fallback))})}
 if(voltage){for(const [name,key] of [['电压下限','voltage_min_pu'],['电压上限','voltage_max_pu'],['线性保护阈值','linear_voltage_guard_pu']] as const)series.push({name,type:'line',symbol:'none',lineStyle:{type:'dashed'},data:rows.map(()=>result.value.network_parameters?.[key]??networkDefaults[key])})}
 plot.setOption({tooltip:{trigger:'axis'},legend:{type:'scroll',data:series.map(s=>s.name)},grid:{left:65,right:25,bottom:75,top:50},dataZoom:[{type:'inside'},{type:'slider',bottom:10,height:20}],xAxis:{type:'category',data:rows.map((r:any)=>r.timestamp.slice(5,16).replace('T',' '))},yAxis:{type:'value',name:voltage?'电压 / pu':soc?'SOC / %':'kW',...(soc?{min:0,max:100}:voltage?{scale:true}:{})},series});
}

async function load(id:string){try{result.value=await api('/api/runs/'+id);customNetwork.value=result.value.network||null;sourceImport.value=result.value.source_import||null;csv.value=result.value.input_csv;sourceImportCsv.value=csv.value;productionId.value=result.value.production_sequence_id||null;productionCsv.value=csv.value;scenarioId.value=result.value.scenario_id||null;params.value={soc_min_ratio:.1,soc_max_ratio:.95,eta_charge:.92,eta_discharge:.9,critical_load_ratio:.2,important_load_ratio:.35,...result.value.parameters};networkParameters.value={...networkDefaults,...result.value.network_parameters};stages.value=normalizeStages(result.value.stages);stageSnapshot.value=JSON.stringify(stages.value);model.value=result.value.model||'aggregate';failedLines.value=(result.value.failed_lines||[]).join(',');branchLimit.value=result.value.branch_limit_kw||5000;active.value='电力电量平衡';subsection.value='平衡结果';await draw()}catch(e){error.value=String(e)}}
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file){csv.value=await file.text();result.value=null}}
watch([active,chartMode,subsection],draw);onMounted(async()=>{try{projects.value=await api('/api/projects');if(projects.value.length)await openProject(projects.value.find(p=>p.id===localStorage.getItem('terminal-power.last-project'))?.id||projects.value[0].id,false);else await createProject();window.addEventListener('resize',()=>plot?.resize())}catch(e){error.value=String(e)}finally{busy.value=false}});
</script>
<template><div class="shell"><aside><div class="brand">▦ 末端保供<span>局域电力系统辅助决策</span></div><nav aria-label="业务菜单"><div v-for="(m,i) in menus" :key="m"><button :class="{selected:active===m}" @click="active=m"><small>{{String(i+1).padStart(2,'0')}}</small>{{m}}</button><div class="submenus" v-if="active===m&&children[m]"><template v-if="m==='数据管理'||m==='电力电量平衡'"><div v-for="group in (m==='数据管理'?dataMenuGroups:balanceMenuGroups)" :key="group.label" class="data-menu-group"><span class="data-menu-label">{{group.label}}</span><button v-for="child in group.items" :key="child" :class="{'sub-selected':subsection===child}" @click="navigateSection(m,child)">{{child}}</button></div></template><template v-else><button v-for="child in children[m]" :class="{'sub-selected':subsection===child}" @click="navigateSection(m,child)">{{child}}</button></template></div></div></nav><footer>本地离线工作空间<br>研发预览版 · 0.1.0</footer></aside><main><header><span>末端保供局域电力系统源储协同配置软件</span><b>● 本地计算</b></header><section><article><div class="actions"><select :value="project?.id" @change="openProject(($event.target as HTMLSelectElement).value)" :disabled="busy"><option v-for="p in projects" :value="p.id">{{p.name}} · v{{p.revision}}</option></select><button @click="createProject" :disabled="busy">新建工程</button><button @click="saveProject().catch(e=>error=String(e))" :disabled="busy||!project">保存工程</button><a class="backup-link" href="/api/backup" title="下载全部已保存工程、场景与计算档案，不含未保存修改">备份已保存数据</a></div><p>{{projectMessage}}</p></article><div class="heading"><div><small>末端保供 / 工程分析工作空间</small><h1>{{active}}</h1></div><span class="tag">课题2分析已接入</span></div><p class="notice">研发边界：当前接入课题2真实平衡算法及八项策略触发。可选择IEEE33节点网络平衡与交流潮流复核；已支持故障状态抽样与连续修复场景；合成数据仅供联调，尚不含经校准的多样本概率评估与动态稳定校核。</p><p v-if="error" class="error">{{error}}</p>
<template v-if="active==='工程工作台'&&project"><ProjectOverview :csv="csv" :history="history" :scenario-id="scenarioId" :production-id="activeProductionId" :model="model" :stages="stages.length" @navigate="active=$event" @open="load"/><article id="project-info"><h3>工程信息</h3><label class="field">工程名称<input v-model="project.name" :disabled="busy"></label><label class="field">所在区域<input v-model="project.region" :disabled="busy"></label><label class="field">工程类型<select v-model="project.kind" :disabled="busy"><option>县域级</option><option>乡镇级</option><option>村级</option><option>村镇级</option></select></label><p>工程数据、资源参数、阶段和场景引用随工程保存。切换前自动保存当前工程。</p></article></template><template v-else-if="active==='数据管理'"><div class="data-page-navigation"><p>数据管理 / {{currentDataGroup?.label}} / {{subsection}}</p><div class="module-tabs" aria-label="当前数据分组导航"><button v-for="item in currentDataGroup?.items" :key="item" :class="{current:subsection===item}" @click="navigateSection('数据管理',item)">{{item}}</button></div></div><EngineeringWorkspace v-if="inventorySections.includes(subsection)" :project-id="project?.id||''" :section="subsection"/><DataGovernance v-else-if="['地理与灾害','数据版本管理'].includes(subsection)" :project-id="project?.id||''" :section="subsection"/><DataWorkspace v-else v-model="csv" v-model:network="customNetwork" @update:network="model='case33'" v-model:failures="faultSelection" @source="(value,source)=>{applyProjected(value);sourceImport=source;sourceImportCsv=value;stages=[];project.region='阿拉山口';projectMessage='阿拉山口典型负荷已应用，请保存工程'}" :section="subsection" :placement="networkParameters" :parameters="params" :disabled="busy"/></template><template v-else-if="active==='保供场景生成'"><article><h3>场景配置与计算流程</h3><p>① 查看来源：典型场景库为预设模板，源荷时序来自当前工程；模板不代表地区实测结果。② 设置参数：选择增长水平、事件窗口或故障修复参数。③ 点击当前模块的生成按钮后调用后端计算，并保存该模块结果。④ 在生成结果中点击应用或嵌入，再进入电力电量平衡运行计算。⑤ 平衡结果在本页对应结果区及方案与报告中查看；修改参数后须重新生成和计算。</p></article><div class="module-tabs"><button v-for="child in children[active]" :class="{current:subsection===child}" @click="subsection=child">{{child}}</button></div><EngineeringWorkspace v-if="['典型场景库','分类目标与优先级'].includes(subsection)" :project-id="project?.id||''" :section="subsection"/><div v-show="subsection==='源荷增长与极端窗口'"><SourceAnalysis :project-id="project?.id||''" :csv="csv" @apply="applyProjected" @window="eventCsv=$event;subsection='生产序列嵌入'"/></div><div v-show="subsection==='近中远期全年背景'"><SourceStudy :project-id="project?.id||''" :csv="csv" :parameters="params" @apply="applyProjected"/></div><div v-show="subsection==='故障与恢复场景'"><ScenarioWorkspace v-if="project" :project-id="project.id" :csv="csv" @apply="applyScenario"/></div><div v-show="subsection==='生产序列嵌入'"><SequenceWorkspace :parameters="params" v-model="eventCsv" :project-id="project?.id||''" :csv="csv" @apply="applyProduction"/></div></template><template v-else-if="active==='电力电量平衡'"><div class="data-page-navigation"><p>电力电量平衡 / {{subsection}}</p><div v-for="group in balanceMenuGroups" :key="group.label"><span>{{group.label}}</span><div class="module-tabs"><button v-for="item in group.items" :key="item" :class="{current:subsection===item}" @click="navigateSection('电力电量平衡',item)">{{item}}</button></div></div></div><div><p v-if="activeProductionId" class="notice">源荷来自生产序列 {{activeProductionId.slice(0,8)}}；计算报告将保留嵌入设置。<button @click="productionId=null" :disabled="busy">解除序列引用</button></p><p v-if="scenarioId" class="notice">已应用故障场景 {{scenarioId.slice(0,8)}} <button @click="scenarioId=null" :disabled="busy">解除场景</button></p><div class="grid" id="balance-input"><article><h3>01 / 输入时序</h3><p>来源：{{activeProductionId?'已保存生产序列':sourceImportCsv===csv&&sourceImport?'阿拉山口原始资料转换':'当前工作区输入（来源需核实）'}}。{{projectMessage}}</p><SeriesPreview :csv="csv"/><button @click="loadAnnualExample" :disabled="busy">载入8760小时合成展示例（替换当前输入）</button><p>连续1小时间隔 · kW · 2–8760行</p><div class="actions"><button @click="demo" :disabled="busy">加载合成算例</button><label class="button">导入CSV<input type="file" accept=".csv" @change="upload" :disabled="busy" hidden></label></div><details><summary>展开CSV原始数据与编辑</summary><textarea v-model="csv" spellcheck="false" :disabled="busy"></textarea></details></article><article><h3>02 / 模型与资源参数</h3><label class="field">计算模型<select v-model="model" :disabled="busy"><option value="aggregate">汇总逐时平衡</option><option value="case33">{{customNetwork?customNetwork.name:'IEEE33示例'}} · 节点网络平衡</option></select></label><details :open="subsection==='模型与资源'"><summary>资源参数、接入节点与故障设置</summary><template v-if="model==='case33'"><p>采用已应用网络（未配置时使用IEEE33示例），2–168小时。负荷按节点基准比例分配，风光接入节点可设置，其余资源接根节点；仅处理根节点连通区域。</p><label class="field">风电接入节点编号<input type="number" min="1" max="99999" step="1" v-model.number="networkParameters.wind_node" :disabled="busy"></label><label class="field">光伏接入节点编号<input type="number" min="1" max="99999" step="1" v-model.number="networkParameters.pv_node" :disabled="busy"></label><label class="field">电压下限 / pu<input type="number" min="0.8" max="1" step="0.001" v-model.number="networkParameters.voltage_min_pu" :disabled="busy"></label><label class="field">电压上限 / pu<input type="number" min="1" max="1.2" step="0.001" v-model.number="networkParameters.voltage_max_pu" :disabled="busy"></label><label class="field">线性调度电压保护阈值 / pu<input type="number" min="0.8" max="1" step="0.001" v-model.number="networkParameters.linear_voltage_guard_pu" :disabled="busy"></label><p>根节点电压固定为1 pu；保护阈值用于线性调度，其值须不小于电压下限。交流潮流另按上下限复核。</p><div><p>全时域故障点（启用阶段后由阶段设置替代）</p><FaultPicker v-model="faultSelection" :lines="currentLines" :disabled="busy"/></div><label class="field">统一支路容量 / kW<input type="number" v-model.number="branchLimit" :disabled="busy"></label></template><label v-for="(_,key) in params" class="field">{{labels[key]}}<input type="number" v-model.number="params[key]" :disabled="busy" :step="key.includes('ratio')||key.startsWith('eta_')?0.01:100" min="0"></label></details><p>关键、重要负荷按占比分组并按优先级供电，剩余为一般负荷；这不等同逐户负荷数据库。无该类负荷时原算法满足率记为1。</p><button class="primary" @click="run" :disabled="busy">{{busy?'正在计算并保存…':'开始平衡分析'}}</button><p>计算结果自动归档；修改输入后需重新计算。</p></article></div><div id="balance-phases"><PhaseEditor v-model="stages" :disabled="busy" :network="model==='case33'" :lines="currentLines" :hours="inspectTimeSeries(csv).count"/></div><details id="balance-device" :open="subsection==='逐设备时序调度'"><summary>逐设备时序调度 · 展开设置与计算</summary><DeviceDispatch :project-id="project?.id||''"/></details><details id="balance-random" :open="subsection==='随机生产模拟'"><summary>随机生产模拟 · 展开设置与计算</summary><RandomBalance :source="result" :project-id="project?.id||''"/></details><details id="balance-annual" :open="subsection==='逐设备年度滚动'"><summary>逐设备年度滚动 · 展开设置与计算</summary><AnnualWorkspace :project-id="project?.id||''"/></details><p id="balance-result" v-if="!result" class="notice">尚无平衡结果，请先开始平衡分析或从工程工作台加载档案。</p><p id="balance-network" v-if="!result" class="notice">尚无网络结果，请选择IEEE33模型计算后查看。</p><template v-if="result"><p class="notice" v-if="activeProductionId!==(result.production_sequence_id||null) || scenarioId!==(result.scenario_id||null) || JSON.stringify(stages)!==stageSnapshot || csv!==result.input_csv || !sameParameters(params,result.parameters) || (model==='case33'&&!sameParameters(networkParameters,{...networkDefaults,...result.network_parameters})) || model!==(result.model||'aggregate') || failedLines!==(result.failed_lines||[]).join(',') || branchLimit!==(result.branch_limit_kw||5000)">输入已修改，下方为上次计算结果，请重新计算。</p><div class="metrics" id="balance-result"><article><span>最大功率缺额</span><strong>{{result.metrics.max_power_deficit_kw.toFixed(2)}} <small>kW</small></strong></article><article><span>累计缺供电量</span><strong>{{result.metrics.expected_energy_deficit_kwh.toFixed(2)}} <small>kWh</small></strong></article><article><span>关键负荷电量满足率</span><strong>{{(100*result.metrics.critical_load_supply_ratio).toFixed(1)}}%</strong></article></div><article><h3>03 / 供需时序曲线</h3><p>{{result.scope}}</p><p v-if="result.model==='case33'">交流最低电压：{{Math.min(...result.rows.map((r:any)=>r.ac_min_voltage_pu)).toFixed(4)}} pu · 电压越限时段：{{result.rows.filter((r:any)=>!r.ac_voltage_within_bounds).length}}</p><div class="actions chart-tabs"><button v-for="mode in (result.model==='case33'?['供需平衡','资源出力','储能SOC','网络电压']:['供需平衡','资源出力','储能SOC'])" :class="{'chart-selected':chartMode===mode}" @click="chartMode=mode">{{mode}}</button></div><p v-if="chartMode==='资源出力'">充电以负值表示，放电以正值表示；各曲线取自本次计算逐时结果。</p><p v-if="chartMode==='储能SOC'">SOC为每个小时调度后的储能状态；虚线为本次计算使用的上下限。</p><p v-if="chartMode==='网络电压'">电压为各小时与根节点连通区域的交流潮流极值，虚线取自本次计算约束；不代表孤岛动态稳定。历史记录未保存最高电压时该曲线留空。</p><div ref="chart" class="chart" :aria-label="chartMode+'逐时曲线'"></div><a :href="'/api/runs/'+result.id+'/csv'">导出完整逐时结果 CSV ↓</a>　<a :href="'/api/runs/'+result.id+'/report'">导出计算报告 HTML ↓</a></article><article v-if="result.phase_metrics"><h3>分阶段电力电量指标</h3><p>当前为单条输入轨迹，缺供比例是阶段内缺供时段占比，并非校准后的灾害概率。</p><div class="scroll"><table><tr><th>阶段</th><th>缺供时段占比 / %</th><th>最大功率缺额 / MW</th><th>缺供电量 / MWh</th><th>弃电量 / MWh</th></tr><tr v-for="p in result.phase_metrics"><td>{{p.stage}}</td><td>{{p.electricity_shortage_probability_pct.toFixed(2)}}</td><td>{{p.maximum_electricity_shortage_mw.toFixed(3)}}</td><td>{{p.expected_energy_not_served_mwh.toFixed(3)}}</td><td>{{p.expected_curtailed_energy_mwh.toFixed(3)}}</td></tr></table></div></article><article><h3>逐时明细（前48行）</h3><div class="scroll"><table><tr><th>时间</th><th>负荷 kW</th><th>供电 kW</th><th>缺供 kW</th><th>SOC</th><th v-if="result.model==='case33'">交流电压范围 / pu</th><th v-if="result.model==='case33'">电压校核</th></tr><tr v-for="r in result.rows.slice(0,48)"><td>{{r.timestamp}}</td><td>{{r.load_kw.toFixed(2)}}</td><td>{{r.load_served_kw.toFixed(2)}}</td><td>{{r.power_deficit_kw.toFixed(2)}}</td><td>{{(r.soc*100).toFixed(1)}}%</td><td v-if="result.model==='case33'">{{r.ac_min_voltage_pu.toFixed(4)}} ～ {{r.ac_max_voltage_pu==null?'未记录':r.ac_max_voltage_pu.toFixed(4)}}</td><td v-if="result.model==='case33'">{{r.ac_voltage_within_bounds?'满足':'越限'}}</td></tr></table></div></article><div id="balance-network"><NetworkResult v-if="result.model==='case33'" :result="result"/><p v-else class="notice">网络逐时结果需选择IEEE33网络模型并计算。</p></div></template><details id="balance-native" :open="subsection==='原生年度流水线'"><summary>原生年度流水线 · 展开设置与计算</summary><NativePipeline :project-id="project?.id||''" :csv="csv" :parameters="params" :network-parameters="networkParameters" :branch-limit="branchLimit"/></details></div></template>
<StrategyWorkspace v-else-if="active==='保供能力提升'" :result="result"/>
<EffectEvaluation v-else-if="active==='方案与报告'&&subsection==='质效评价'" :project-id="project?.id||''"/><DeliverablesWorkspace v-else-if="active==='方案与报告'&&['示范区实证','成果与交付'].includes(subsection)" :project-id="project?.id||''" :section="subsection"/><ReportWorkspace v-else-if="active==='方案与报告'" :project-id="project?.id||''" @open="load"/>
<StudyTasks v-else-if="active==='系统与接口'&&subsection==='计算任务'" :project-id="project?.id||''"/><DevelopmentPlan v-else-if="active==='系统与接口'&&subsection==='功能规划与验收'"/><IntegrationWorkspace :initial-module="integrationModule" v-else-if="active==='系统与接口'" :project-id="project?.id||''"/><DisasterWorkspace v-else-if="active==='承灾极限分析'" :project-id="project?.id||''" :section="subsection"/><RestorationWorkspace v-else-if="active==='黑启动路径优化'" :project-id="project?.id||''" :section="subsection"/><InvestmentWorkspace v-else-if="active==='源储协同配置'" :project-id="project?.id||''" :section="subsection"/><ModuleWorkspace @integration="openIntegration" v-else :section="subsection" :module="active" :project-id="project?.id||'legacy'" />
</section></main></div></template>
